WITH metrics AS (SELECT *, NTILE(5) OVER (PARTITION BY product_id ORDER BY quantity, id) AS quantity_bucket, NTILE(3) OVER (PARTITION BY store_id ORDER BY quantity DESC, id) AS quantity_bucket_2, PERCENT_RANK() OVER (ORDER BY quantity) AS quantity_percent_rank, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity_2 FROM inventory), enriched AS (SELECT src.*, s.region, s.sqft FROM metrics src LEFT JOIN stores s ON src.store_id = s.id), remaining_keys AS (SELECT product_id, store_id FROM enriched INTERSECT ALL SELECT product_id, store_id FROM inventory WHERE quantity BETWEEN 71 AND 119), reconciled AS (SELECT s.* FROM enriched s JOIN remaining_keys k ON s.product_id = k.product_id AND s.store_id = k.store_id), filtered AS (SELECT id, product_id, quantity, quantity_bucket, quantity_bucket_2, quantity_percent_rank, last_known_quantity, last_known_quantity_2, LAST_DAY(last_restock) AS last_restock_month_end, COALESCE(region, 'N/A') AS resolved_region FROM reconciled WHERE last_restock > TO_DATE('2023-04-13')), with_windows AS (SELECT id, product_id, quantity, quantity_bucket, quantity_bucket_2, quantity_percent_rank, last_known_quantity, last_known_quantity_2, last_restock_month_end, resolved_region, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY last_known_quantity_2 DESC NULLS FIRST) AS last_known_quantity_2_dense_rank, AVG(last_known_quantity) OVER (PARTITION BY product_id) AS product_id_avg_last_known_quantity, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY last_known_quantity_2 DESC NULLS FIRST) AS last_known_quantity_2_percent_rank FROM filtered), matched_keys AS (SELECT id, product_id FROM with_windows EXCEPT SELECT id, product_id FROM inventory WHERE product_id = 5), kept_rows AS (SELECT s.* FROM with_windows s JOIN matched_keys k ON s.id = k.id AND s.product_id = k.product_id), enriched_inventory AS (SELECT *, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY last_known_quantity_2 DESC NULLS LAST) AS last_known_quantity_2_dense_rank_2, CUME_DIST() OVER (ORDER BY quantity) AS quantity_cume_dist, MIN(product_id_avg_last_known_quantity) OVER (PARTITION BY product_id) AS product_id_min_product_id_avg_last_known_quantity FROM kept_rows) SELECT id, product_id, quantity, quantity_bucket, quantity_percent_rank, last_known_quantity, resolved_region, last_known_quantity_2_dense_rank, last_known_quantity_2_percent_rank FROM enriched_inventory ORDER BY product_id, last_known_quantity_2_dense_rank;
